package e.e.a;
import android.app.Activity;import android.view.*;import android.widget.*;
/** Add a save action to the native player's existing menu container. */
public final class PlayerDownloads116 {
 static final java.util.WeakHashMap<View,java.lang.ref.WeakReference<Watcher>> WAITING=new java.util.WeakHashMap<>();
 static final String TAG="nicoid-save-mp4-116";
 public static void attach(Object owner){try{View root=(View)Playback214.get(owner,"x1");Activity a=(Activity)Playback214.get(owner,"A1");if(root==null||a==null)return;root.post(()->{install(owner,a,root);if(root.findViewWithTag(TAG)==null&&!a.isFinishing()&&!a.isDestroyed()){java.lang.ref.WeakReference<Watcher> old=WAITING.get(root);if(old==null||old.get()==null){Watcher w=new Watcher(owner,a,root);WAITING.put(root,new java.lang.ref.WeakReference<>(w));root.getViewTreeObserver().addOnGlobalLayoutListener(w);root.addOnAttachStateChangeListener(w);}}});}catch(Exception e){android.util.Log.w("nicoid-download","Cannot schedule player save action",e);}}
 static void install(Object owner,Activity a,View root){if(a.isFinishing()||a.isDestroyed()||root.findViewWithTag(TAG)!=null)return;try{if(Playback214.get(owner,"x1")!=root)return;int id=root.getResources().getIdentifier("videomenulist","id",a.getPackageName());View menu=id==0?null:root.findViewById(id);TextView row=PanelUi.text(a,PanelUi.tr(a,"MP4で保存","Save as MP4","另存為MP4"),16);row.setTag(TAG);row.setGravity(Gravity.CENTER_VERTICAL);row.setMinHeight(PanelUi.dp(a,48));row.setPadding(PanelUi.dp(a,16),PanelUi.dp(a,8),PanelUi.dp(a,16),PanelUi.dp(a,8));row.setBackgroundColor(android.graphics.Color.TRANSPARENT);row.setOnClickListener(v->{try{String video=HistoryRules.id(String.valueOf(Playback214.get(owner,"b0")));if(video==null||!video.matches("(?:sm|so|nm|ss)?[0-9]+"))return;String title=String.valueOf(Playback214.get(owner,"c0"));if(title.equals("null")||title.isEmpty())title=video;DownloadUi115.choose(a,video,title);}catch(Exception e){android.util.Log.w("nicoid-download","Cannot save current video",e);}});
  if(menu instanceof ListView){((ListView)menu).addFooterView(row,null,false);return;}if(menu instanceof LinearLayout){LinearLayout group=(LinearLayout)menu;int at=cacheIndex(group);group.addView(row,at,new LinearLayout.LayoutParams(-1,-2));return;}
  View cache=findCache(root);if(cache!=null&&cache.getParent() instanceof LinearLayout){LinearLayout group=(LinearLayout)cache.getParent();group.addView(row,group.indexOfChild(cache)+1,new LinearLayout.LayoutParams(-1,-2));return;}
 }catch(Exception e){android.util.Log.w("nicoid-download","Cannot attach player save action",e);}}
 static final class Watcher implements android.view.ViewTreeObserver.OnGlobalLayoutListener,View.OnAttachStateChangeListener{final java.lang.ref.WeakReference<Object> owner;final Activity activity;final View root;Watcher(Object o,Activity a,View r){owner=new java.lang.ref.WeakReference<>(o);activity=a;root=r;}public void onGlobalLayout(){Object o=owner.get();if(o==null||activity.isFinishing()||activity.isDestroyed()){stop();return;}try{if(Playback214.get(o,"x1")!=root){stop();return;}}catch(Exception e){stop();return;}install(o,activity,root);if(root.findViewWithTag(TAG)!=null)stop();}void stop(){if(root.getViewTreeObserver().isAlive())root.getViewTreeObserver().removeOnGlobalLayoutListener(this);root.removeOnAttachStateChangeListener(this);java.lang.ref.WeakReference<Watcher> current=WAITING.get(root);if(current!=null&&current.get()==this)WAITING.remove(root);}public void onViewAttachedToWindow(View v){onGlobalLayout();}public void onViewDetachedFromWindow(View v){stop();}}
 static boolean cacheText(View v){if(!(v instanceof TextView))return false;String text=((TextView)v).getText().toString();String translated=UiStrings.translate("キャッシュ取得");return text.startsWith(translated)||text.startsWith("キャッシュ取得");}
 static View findCache(View root){if(cacheText(root))return root;if(root instanceof ViewGroup){ViewGroup group=(ViewGroup)root;for(int n=0;n<group.getChildCount();n++){View found=findCache(group.getChildAt(n));if(found!=null)return found;}}return null;}
 static int cacheIndex(ViewGroup group){for(int n=0;n<group.getChildCount();n++)if(findCache(group.getChildAt(n))!=null)return n+1;return 0;}
}
